// Get all members as users
export function getRealUsers(): UserData[] {
  return REAL_MEMBERS.map((m) => ({
    id: m.sn,
    fullName: m.name,
    email: m.email,
    role: m.package === "STANDARD" ? "reseller" : "customer",
    status: "active",
    phone: m.phone,
    createdAt: m.startDate,
    lastLogin: m.startDate,
    cards: 1,
    plan: PLAN_MAP[m.package] || "Free",
  }));
}

// Get all members as customers
export function getRealCustomers(): CustomerData[] {
  return REAL_MEMBERS.map((m) => ({
    id: m.sn,
    fullName: m.name,
    email: m.email,
    phone: m.phone,
    businessName: m.name,
    plan: PLAN_MAP[m.package] || "Free",
    status: "active",
    cards: 1,
    totalViews: Math.floor(Math.random() * 5000) + 100,
    leads: Math.floor(Math.random() * 50) + 1,
    createdAt: m.startDate,
    lastActive: m.startDate,
    city: "India",
  }));
}

// Get resellers only (STANDARD package members)
export function getRealResellers() {
  return REAL_MEMBERS.filter((m) => m.package === "STANDARD");
}

// Get stats
export function getMemberStats() {
  const total = REAL_MEMBERS.length;
  const trial = REAL_MEMBERS.filter((m) => m.package === "Trial" || m.package === "Trail").length;
  const standard = REAL_MEMBERS.filter((m) => m.package === "STANDARD").length;
  const starter = REAL_MEMBERS.filter((m) => m.package === "STARTER").length;
  const free = REAL_MEMBERS.filter((m) => m.package === "").length;
  return { total, trial, standard, starter, free, resellers: standard };
}
